import{_ as e,o,c as t,a8 as i}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.68 小程序的双线程秘密","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.68-wechat-miniprogram.md","filePath":"comics/EP.68-wechat-miniprogram.md","lastUpdated":1793706365000}'),l={name:"comics/EP.68-wechat-miniprogram.md"};function r(n,a,s,d,c,h){return o(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="ep-68-小程序的双线程秘密" tabindex="-1">EP.68 小程序的双线程秘密 <a class="header-anchor" href="#ep-68-小程序的双线程秘密" aria-label="Permalink to &quot;EP.68 小程序的双线程秘密&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../94-wechat-miniprogram">94-wechat-miniprogram.md</a>（94.1 双线程模型 / 94.2 生命周期 / 94.4 分包 / 94.5 登录）· 示例：<code>examples/94-01-wechat-miniprogram.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：setData 频繁全量传导致页面卡顿。</li><li><strong>第 2 格</strong>：码叔揭秘双线程模型——逻辑层(JSCore)与渲染层(WebView)隔离，setData 是唯一通道。</li><li><strong>第 3 格</strong>：像素酱实证生命周期顺序与登录流程。</li><li><strong>第 4 格</strong>：码叔结案——分包策略与组件通信（properties+triggerEvent）。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-setdata-性能" tabindex="-1">第 1 格 · setData 性能 <a class="header-anchor" href="#第-1-格-·-setdata-性能" aria-label="Permalink to &quot;第 1 格 · setData 性能&quot;">​</a></h3><ul><li>双线程间数据需序列化传输；</li><li>全量 <code>setData(this.data)</code> 浪费；</li><li>应用路径更新只传变化字段，单次 &lt; 256KB。</li></ul><h3 id="第-2-格-·-双线程模型" tabindex="-1">第 2 格 · 双线程模型 <a class="header-anchor" href="#第-2-格-·-双线程模型" aria-label="Permalink to &quot;第 2 格 · 双线程模型&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>逻辑层(JSCore) ←setData→ 渲染层(WebView)</span></span></code></pre></div><ul><li>逻辑层跑 JS，渲染层渲染 WXML；</li><li>两层隔离，setData 是唯一通信通道；</li><li>用路径 <code>&quot;user.name&quot;</code> 更新嵌套字段。</li></ul><h3 id="第-3-格-·-生命周期与登录" tabindex="-1">第 3 格 · 生命周期与登录 <a class="header-anchor" href="#第-3-格-·-生命周期与登录" aria-label="Permalink to &quot;第 3 格 · 生命周期与登录&quot;">​</a></h3><ul><li>Page：onLoad→onShow→onReady→onHide→onUnload；</li><li>登录：<code>wx.login()</code>→code→后端<code>code2session</code>换 openid→签发 token。</li></ul><h3 id="第-4-格-·-分包与组件通信" tabindex="-1">第 4 格 · 分包与组件通信 <a class="header-anchor" href="#第-4-格-·-分包与组件通信" aria-label="Permalink to &quot;第 4 格 · 分包与组件通信&quot;">​</a></h3><ul><li>主包≤2MB 放首屏+tabBar，分包按需加载；</li><li>父→子用 properties，子→父用 triggerEvent。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../94-wechat-miniprogram#_94-7-本章避坑清单">《94.7 本章避坑清单》</a></p></blockquote><ol><li><code>setData(this.data)</code> 全量传 → 用路径只传变化字段；</li><li><code>list[0].name</code> 不生效 → 小程序用 <code>list.0.name</code>；</li><li>onUnload 不清定时器 → 内存泄漏。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>小程序为什么用双线程模型？——<strong>安全管控：逻辑层无 DOM/BOM，渲染层隔离，防止直接操作 DOM</strong>。</li><li>Page 生命周期顺序？——<strong>onLoad→onShow→onReady→onHide→onUnload</strong>。</li><li>小程序分包大小限制？——<strong>主包≤2MB，单分包≤2MB，总包≤20MB</strong>。</li></ol>',19)])])}const m=e(l,[["render",r]]);export{u as __pageData,m as default};
